export const GLOSSARY = [
 ['x ∈ A / E ⊆ A','x является элементом A / каждый элемент E принадлежит A. Для включения допускается E=A.'],
 ['A × B','Декартово произведение: множество всех упорядоченных пар (a,b), где a∈A и b∈B.'],
 ['R ⊆ A × B','Бинарное отношение из A в B. Оно задаёт функцию, если для каждого x∈A существует ровно один y∈B с (x,y)∈R.'],
 ['∀ / ∃ / ∃!','Для каждого / существует / существует ровно один. Перестановка кванторов может изменить истинность утверждения.'],
 ['f: A → B','Функция с областью определения A и кодоменом B. Каждому x∈A соответствует ровно одно значение f(x)∈B.'],
 ['x ↦ f(x)','Запись соответствия аргумента x значению f(x). Символ f обозначает функцию, f(x) — её значение при x.'],
 ['dom f','Область определения функции f.'],
 ['f(A)','Образ функции на A: {f(x): x∈A}. Образ является подмножеством кодомена B. Область значений в этом курсе — синоним образа.'],
 ['Инъекция','Для любых x₁,x₂∈A из f(x₁)=f(x₂) следует x₁=x₂.'],
 ['Сюръекция на B','Для каждого y∈B существует x∈A, для которого f(x)=y. Эквивалентно: f(A)=B.'],
 ['Биекция','Функция, одновременно являющаяся инъекцией и сюръекцией.'],
 ['|A|','Мощность множества A. Для конечного A это число его элементов. Равенство |A|=|B| означает существование биекции A→B.'],
 ['𝒫(A)','Множество всех подмножеств A. Его элементы — множества E⊆A.'],
 ['Обратная функция f⁻¹: B→A','Для биекции f: A→B обратная функция удовлетворяет f⁻¹(f(x))=x и f(f⁻¹(y))=y. Это не функция 1/f.'],
 ['Полный прообраз f⁻¹(E)','Множество {x∈A: f(x)∈E} для E⊆B. Определено для любой функции; существование обратной функции не требуется.'],
 ['s ∘ r','Композиция: (s∘r)(x)=s(r(x)). Для r: A→B и s: B→C это функция A→C.'],
 ['id_A','Тождественная функция на A: id_A(x)=x для всех x∈A.'],
 ['∅ / A ∖ B / A ∪ B','Пустое множество / элементы A, не принадлежащие B / элементы, принадлежащие хотя бы одному из множеств A и B.'],
 ['ℝ / [a,b] / (a,b)','Множество вещественных чисел / отрезок a≤x≤b / интервал a<x<b.']
];

GLOSSARY.push(['∫ₐᵇ f(x)dx','Определённый интеграл; для интеграла Римана используется предел интегральных сумм.'],['o(‖h‖)','Остаток r(h), для которого ‖r(h)‖/‖h‖→0 при h→0.'],['∇f','Градиент скалярной функции: вектор её частных производных.'],['Jf, det Jf','Матрица Якоби и её определитель, когда матрица квадратная.'],['fₙ ⇒ f','Равномерная сходимость: один номер N подходит для всех точек области.'],['sup','Точная верхняя граница множества; она может не принадлежать множеству.'],['C¹, C²','Классы функций с непрерывными частными производными до первого или второго порядка.'],['rot F, div F','Ротор и дивергенция векторного поля.'],['ds, dS, dV','Элементы длины, площади поверхности и объёма.'],['L²','Класс функций с интегрируемым квадратом модуля; функции, равные почти всюду, отождествляются.']);

GLOSSARY.push(['Uδ(a)','δ-окрестность a∈ℝ: интервал (a−δ,a+δ), δ>0.'],['U̇δ(a)','Проколотая окрестность: 0<|x−a|<δ; точка a исключена.'],['Предельная точка','Каждая проколотая окрестность точки содержит элемент рассматриваемого множества.'],['Изолированная точка','Принадлежит множеству, но некоторая её окрестность не содержит других его точек.'],['Внутренняя точка','Некоторая окрестность целиком содержится в множестве.'],['Граничная точка','Любая окрестность встречает и множество, и его дополнение.'],['inf A','Инфимум: наибольшая нижняя грань A.'],['max A, min A','Наибольший и наименьший элементы самого множества. Точные грани не обязаны достигаться.'],['Полнота ℝ','Каждое непустое ограниченное сверху подмножество ℝ имеет вещественный супремум.'],['Предел последовательности','aₙ→A: для каждого ε>0 существует N, при всех n>N выполнено |aₙ−A|<ε.'],['Предел функции','limₓ→ₐf=L: для каждого ε>0 существует δ>0, при x∈D, 0<|x−a|<δ имеем |f(x)−L|<ε. Точка a предельная для D.'],['Критерий Коши','Сходимость в полном пространстве равносильна сколь угодно малым различиям любых двух достаточно поздних членов.'],['limsup, liminf','Верхний и нижний пределы: пределы супремумов и инфимумов хвостов последовательности.'],['Непрерывность','Значения f(x) близки к f(a) для всех аргументов области, достаточно близких к a.'],['Равномерная непрерывность','Для каждого ε один δ подходит сразу для всех пар точек области.'],['f′(a)','Конечный предел [f(a+h)−f(a)]/h при h→0, h≠0.'],['O(g)','f=O(g): |f|≤C|g| в некоторой рассматриваемой окрестности. Предельный переход указывают.'],['Компактность','Из любого открытого покрытия выделяется конечное подпокрытие. В ℝⁿ равносильна замкнутости и ограниченности.'],['Операторная норма','‖L‖=sup{‖Lx‖:‖x‖≤1}. Нормы в исходном и конечном пространствах должны быть заданы.']);

GLOSSARY.push(['σ-алгебра','Семейство множеств, содержащее всё пространство и замкнутое относительно дополнения и счётного объединения.'],['Мера','Неотрицательная счётно аддитивная функция на σ-алгебре, равная нулю на пустом множестве.'],['Почти всюду','Свойство выполнено вне множества меры ноль.'],['L¹','Классы измеримых функций с конечным интегралом модуля; равные почти всюду функции отождествляются.'],['Мажоранта','Общая оценка |fₙ|≤g. В теореме Лебега требуется одна g∈L¹ для всей последовательности.'],['Многообразие','Множество с локальными гладкими координатами фиксированной размерности и согласованными переходами.'],['Касательное пространство','Линейное пространство скоростей гладких кривых на многообразии в заданной точке.'],['Свёртка','(f*g)(x)=∫f(x−y)g(y)dy там, где интеграл существует.'],['Мера Хаусдорфа','Мера размерности k, построенная покрытиями малыми множествами и суммами k-х степеней их диаметров.'],['Дифференциальная форма','Гладкое поле кососимметричных многолинейных форм на касательных пространствах.'],['Замкнутая форма','Дифференциальная форма ω с dω=0.'],['Точная форма','Форма вида ω=dη. Точность влечёт замкнутость при достаточной гладкости.'],['Преобразование Фурье','В принятой нормировке f̂(ξ)=∫ℝⁿ f(x)e⁻ⁱˣ·ξdx для f∈L¹.'],['Пространство Шварца','Гладкие функции, для которых все произведения xᵅDᵝf ограничены.']);
